// === Tab: mySketch ===
let t = 0;
let angleY = 0;

let rows = 90;
let cols = 180;
let radius = 260;

function setup() {
  createCanvas(800, 800, WEBGL);
  frameRate(60);
  smooth(0);
  noCursor();
}

function draw() {
  background(0);
  translate(width / 2, height / 2);

  rotateX(HALF_PI);
  rotateZ(radians(-10));
  rotateY(angleY);

  stroke(255);
  strokeWeight(0.5);

  let freq = 10.0;
  let pulseSpeed = 0.02;

  for (i = 0; i < rows; i++) {
    let y = map(i, 0, rows - 1, -radius * 0.8, radius * 0.8);

    for (j = 0; j < cols; j++) {
      let theta = map(j, 0, cols, 0, TWO_PI);
      let x = radius * cos(theta);
      let z = radius * sin(theta);

      // sequenza binaria ritmica su righe e colonne
      let pulse = sin(t * 8 + i * 0.15 + j * 0.05);
      let wave = sin(theta * freq + t * 4.0 + i * 0.1);

      // controllo binario: solo alcuni punti attivi
      if (pulse > 0.95 && wave > 0.2) {
        // variazione: linee alternate orizzontali / verticali
        if ((i + j) % 2 == 0) {
          line(x - 1.5, y, z, x + 1.5, y, z); // orizzontale
        } else {
          line(x, y - 1.5, z, x, y + 1.5, z); // verticale
        }
      }
    }
  }

  t += pulseSpeed;
  angleY += 0.0015;
}

